//! Every engine command reaches MCP or says why not, and `crates/rc-mcp/mcp-coverage.md` says
//! so.
//!
//! A new command in `rc_engine::COMMANDS` without a row in `rc_mcp::coverage::COVERAGE` fails
//! here, as does a row for a command that is gone, a `Covered` tool the server does not serve,
//! and a served tool no row names. The page is generated by `scripts/mcp-coverage.sh`; the last
//! test fails when it no longer matches the tables.

use std::{collections::BTreeSet, path::PathBuf};

use rc_engine::{COMMANDS, CommandClass};
use rc_mcp::{
    RcMcpServer,
    coverage::{COVERAGE, Coverage, render_markdown},
};

#[test]
fn every_command_has_exactly_one_coverage_row_and_every_row_a_command() {
    let commands: Vec<&str> = COMMANDS.iter().map(|spec| spec.id).collect();
    let rows: Vec<&str> = COVERAGE.iter().map(|(id, _)| *id).collect();
    let missing: Vec<&&str> = commands.iter().filter(|id| !rows.contains(id)).collect();
    assert!(
        missing.is_empty(),
        "commands without an MCP coverage entry (add Covered or Omitted to rc-mcp/src/coverage/<group>.rs): {missing:?}"
    );
    let stale: Vec<&&str> = rows.iter().filter(|id| !commands.contains(id)).collect();
    assert!(
        stale.is_empty(),
        "coverage rows for unknown commands: {stale:?}"
    );
    let unique: BTreeSet<&str> = rows.iter().copied().collect();
    assert_eq!(unique.len(), rows.len(), "a command has two rows");
    // `COMMANDS` is the registry's groups in order, each sorted by id: so are the coverage rows.
    assert_eq!(
        rows, commands,
        "keep each group's rows in coverage/<group>.rs, sorted by id"
    );
}

#[test]
fn covered_tools_exist_and_every_tool_covers_a_command() {
    let served: BTreeSet<String> = RcMcpServer::tool_names().into_iter().collect();
    let covered: BTreeSet<String> = COVERAGE
        .iter()
        .filter_map(|(_, coverage)| match coverage {
            Coverage::Covered(tool) => Some((*tool).to_owned()),
            Coverage::Omitted(_) => None,
        })
        .collect();
    let unserved: Vec<&String> = covered.difference(&served).collect();
    assert!(
        unserved.is_empty(),
        "covered by tools that do not exist: {unserved:?}"
    );
    let unlisted: Vec<&String> = served.difference(&covered).collect();
    assert!(
        unlisted.is_empty(),
        "tools that cover no command: {unlisted:?}"
    );
}

#[test]
fn an_omission_gives_a_reason() {
    for (id, coverage) in COVERAGE {
        if let Coverage::Omitted(reason) = coverage {
            assert!(reason.trim().len() >= 10, "{id}: say why it is omitted");
        }
    }
}

#[test]
fn no_tool_reaches_a_gui_only_command() {
    for spec in COMMANDS
        .iter()
        .filter(|spec| spec.class == CommandClass::GuiOnly)
    {
        let row = COVERAGE.iter().find(|(id, _)| *id == spec.id);
        assert_eq!(
            row.map(|(_, coverage)| *coverage),
            Some(Coverage::Omitted("GUI only: human decision")),
            "{} is a human decision; MCP gets no tool for it",
            spec.id
        );
    }
    for (id, coverage) in COVERAGE {
        if let Coverage::Covered(tool) = coverage {
            let class = COMMANDS
                .iter()
                .find(|spec| spec.id == *id)
                .map(|spec| spec.class);
            assert_ne!(
                class,
                Some(CommandClass::GuiOnly),
                "{tool} wraps the GUI-only {id}"
            );
        }
    }
}

/// The non-test sources under `dir`, recursively.
fn sources(dir: &std::path::Path, found: &mut Vec<PathBuf>) {
    for entry in std::fs::read_dir(dir).expect("src is readable") {
        let path = entry.expect("src entry").path();
        if path.is_dir() {
            sources(&path, found);
        } else if path.extension().is_some_and(|ext| ext == "rs")
            && !path.to_string_lossy().ends_with("_tests.rs")
            && !path.ends_with("test_support.rs")
        {
            found.push(path);
        }
    }
}

/// Every engine call of the server goes through `Engine::dispatch_mcp`, which refuses a
/// GUI-only command; the unguarded `dispatch` is not called anywhere in rc-mcp.
#[test]
fn the_server_calls_only_dispatch_mcp() {
    let mut files = Vec::new();
    sources(
        &PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src"),
        &mut files,
    );
    let unguarded: Vec<String> = files
        .iter()
        .filter(|path| {
            std::fs::read_to_string(path)
                .expect("source is UTF-8")
                .contains(".dispatch(")
        })
        .map(|path| path.display().to_string())
        .collect();
    assert!(
        unguarded.is_empty(),
        "call Engine::dispatch_mcp, never dispatch: {unguarded:?}"
    );
}

#[test]
fn the_page_carries_the_generated_table() {
    let page = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("mcp-coverage.md");
    let written = std::fs::read_to_string(&page).unwrap_or_default();
    assert_eq!(
        written,
        render_markdown(),
        "crates/rc-mcp/mcp-coverage.md is stale: run scripts/mcp-coverage.sh"
    );
}
